// ==================== HELPER FORMATTING & UTILS ====================
const formatRP = (val) => new Intl.NumberFormat('id-ID', { 
    style: 'currency', currency: 'IDR', maximumFractionDigits: 0 
}).format(val || 0);

const formatInputWithDots = (val) => {
    if (!val && val !== 0) return '';
    let value = val.toString().replace(/\D/g, ''); 
    return value.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
};

const parseRawNumber = (val) => {
    if (!val) return 0;
    return parseInt(val.toString().replace(/\D/g, ''), 10) || 0;
};

// Membersihkan object dari nilai undefined/null agar Firebase tidak error
const sanitizePayload = (obj) => {
    const cleaned = {};
    Object.keys(obj).forEach(key => {
        if (obj[key] !== undefined && obj[key] !== null) {
            cleaned[key] = obj[key];
        } else {
            cleaned[key] = '';
        }
    });
    return cleaned;
};

// Helper Menghitung Rentang Tanggal Senin-Minggu Secara Otomatis Berdasarkan Waktu Lokal Saat Ini
const getWeeklyDates = () => {
    const now = new Date();
    const dayOfWeek = now.getDay(); // 0 = Minggu, 1 = Senin, ...
    const distanceToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    
    const monday = new Date(now);
    monday.setDate(now.getDate() + distanceToMonday);

    const days = ['senin', 'selasa', 'rabu', 'kamis', 'jumat', 'sabtu', 'minggu'];
    const result = {};

    days.forEach((day, index) => {
        const currentDate = new Date(monday);
        currentDate.setDate(monday.getDate() + index);
        
        const dd = String(currentDate.getDate()).padStart(2, '0');
        const mm = String(currentDate.getMonth() + 1).padStart(2, '0');
        const yyyy = currentDate.getFullYear();
        
        result[day] = `${dd}/${mm}/${yyyy}`;
    });

    return result;
};

